from __future__ import annotations

from typing import Any

from pricing_rules import apply_coupon_discount, apply_loyalty_discount, apply_volume_discount


def calculate_total(payload: dict[str, Any]) -> dict[str, Any]:
    subtotal = float(payload.get("subtotal", 0.0))
    customer_tier = str(payload.get("customer_tier", "standard")).strip().lower()
    quantity = int(payload.get("quantity", 1))
    coupon_code = str(payload.get("coupon_code", "")).strip().upper()

    if subtotal < 0:
        return {"ok": False, "reason": "invalid_subtotal", "total": 0.0}
    if quantity <= 0:
        return {"ok": False, "reason": "invalid_quantity", "total": 0.0}

    discount_pct = 0.0
    discount_reason = "none"

    # Legacy branch-heavy flow to be refactored into strategies.
    if coupon_code:
        discount_pct, discount_reason = apply_coupon_discount(coupon_code, subtotal)
    elif customer_tier in {"gold", "platinum"}:
        discount_pct, discount_reason = apply_loyalty_discount(customer_tier, subtotal)
    elif quantity >= 10:
        discount_pct, discount_reason = apply_volume_discount(quantity, subtotal)
    else:
        discount_pct = 0.0
        discount_reason = "none"

    tax_pct = 0.10
    discounted = subtotal - (subtotal * discount_pct)
    total = discounted + (discounted * tax_pct)
    return {
        "ok": True,
        "reason": "calculated",
        "discount_reason": discount_reason,
        "discount_pct": round(discount_pct, 4),
        "total": round(total, 2),
    }


def calculate_batch(payloads: list[dict[str, Any]]) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = calculate_total(payload)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}

