from __future__ import annotations


COUPON_RULES = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
    "BULK5": 0.05,
}


def apply_coupon_discount(coupon_code: str, subtotal: float) -> tuple[float, str]:
    if subtotal <= 0:
        return (0.0, "coupon_not_applicable")
    pct = COUPON_RULES.get(coupon_code, 0.0)
    if pct <= 0:
        return (0.0, "coupon_invalid")
    if coupon_code == "SAVE20" and subtotal < 100:
        return (0.0, "coupon_minimum_not_met")
    return (pct, "coupon")


def apply_loyalty_discount(customer_tier: str, subtotal: float) -> tuple[float, str]:
    if subtotal <= 0:
        return (0.0, "loyalty_not_applicable")
    if customer_tier == "gold":
        return (0.08, "loyalty")
    if customer_tier == "platinum":
        # Bug: platinum should be higher than gold, but currently lower.
        return (0.06, "loyalty")
    return (0.0, "loyalty_none")


def apply_volume_discount(quantity: int, subtotal: float) -> tuple[float, str]:
    if quantity < 10:
        return (0.0, "volume_not_applicable")
    if subtotal <= 0:
        return (0.0, "volume_not_applicable")
    if quantity >= 50:
        return (0.12, "volume")
    if quantity >= 20:
        return (0.08, "volume")
    return (0.04, "volume")


def supported_coupons() -> list[str]:
    return sorted(COUPON_RULES.keys())


def is_known_tier(tier: str) -> bool:
    return tier in {"standard", "gold", "platinum"}


def clamp_discount_pct(value: float) -> float:
    if value < 0:
        return 0.0
    if value > 0.90:
        return 0.90
    return value

