from pricing_engine import calculate_total


def test_happy_path_platinum_discount_beats_gold():
    gold = calculate_total(
        {"subtotal": 200.0, "customer_tier": "gold", "quantity": 1, "coupon_code": ""}
    )
    platinum = calculate_total(
        {"subtotal": 200.0, "customer_tier": "platinum", "quantity": 1, "coupon_code": ""}
    )
    assert gold["ok"] is True
    assert platinum["ok"] is True
    assert platinum["discount_pct"] > gold["discount_pct"]


def test_edge_case_coupon_priority_over_loyalty():
    result = calculate_total(
        {"subtotal": 200.0, "customer_tier": "platinum", "quantity": 1, "coupon_code": "SAVE10"}
    )
    assert result["ok"] is True
    assert result["discount_reason"] == "coupon"
    assert result["discount_pct"] == 0.10


def test_boundary_condition_save20_requires_minimum_subtotal():
    result = calculate_total(
        {"subtotal": 99.99, "customer_tier": "standard", "quantity": 1, "coupon_code": "SAVE20"}
    )
    assert result["ok"] is True
    assert result["discount_pct"] == 0.0
    assert result["discount_reason"] == "coupon_minimum_not_met"


def test_unexpected_input_invalid_quantity_rejected():
    result = calculate_total(
        {"subtotal": 100.0, "customer_tier": "standard", "quantity": 0, "coupon_code": ""}
    )
    assert result["ok"] is False
    assert result["reason"] == "invalid_quantity"
